shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/test/xchar-test.cc
+++ b/test/xchar-test.cc
@@ -440,6 +440,40 @@ TEST(locale_test, localized_double) {
   EXPECT_EQ(fmt::format(loc, "{:8L}", 1230.0), "   1~230");
 }

+TEST(locale_test, localized_float_alignment) {
+  auto loc = std::locale(std::locale(), new numpunct<char>());
+  auto wloc = std::locale(std::locale(), new numpunct<wchar_t>());
+  struct test_case {
+    double value;
+    const char* expected;
+  };
+  const test_case cases[] = {{-119.921, "-119?921"},
+                             {2194.139, "2~194?139"},
+                             {-57.639, "-57?639"},
+                             {-5.980, "-5?980"},
+                             {-2.119, "-2?119"},
+                             {0.295, "0?295"},
+                             {1.295, "1?295"},
+                             {12.345, "12?345"},
+                             {1234567.89, "1~234~567?890"},
+                             {999.9999, "1~000?000"},
+                             {0.000295, "0?000"},
+                             {0.0, "0?000"},
+                             {-0.0, "-0?000"}};
+  for (const auto& test : cases) {
+    auto expected = std::string(test.expected);
+    auto padding = 19 - expected.size();
+    EXPECT_EQ(std::string(padding, ' ') + expected,
+              fmt::format(loc, "{:19.3Lf}", test.value));
+    EXPECT_EQ(expected + std::string(padding, '*'),
+              fmt::format(loc, "{:*<19.3Lf}", test.value));
+    EXPECT_EQ(std::string(padding / 2, '*') + expected +
+                  std::string(padding - padding / 2, '*'),
+              fmt::format(loc, "{:*^19.3Lf}", test.value));
+    EXPECT_EQ(std::wstring(padding, L' ') +
+                  std::wstring(expected.begin(), expected.end()),
+              fmt::format(wloc, L"{:19.3Lf}", test.value));
+  }
+}
+
